<?php
require_once __DIR__ . '/../conexion.php'; $mensaje=""; $clase="success";
if($_SERVER["REQUEST_METHOD"]==="POST"){
 try{$s=$conexion->prepare("INSERT INTO alumnos(matricula_al,nombre_al,apaterno_al,amaterno_al,dom_al,mail_al,tel_al,estatus_al) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param("ssssssss",$_POST["matricula"],$_POST["nombre"],$_POST["apaterno"],$_POST["amaterno"],$_POST["domicilio"],$_POST["correo"],$_POST["telefono"],$_POST["estatus"]);$s->execute();$mensaje="Alumno registrado correctamente.";}catch(Throwable $e){$mensaje="Error: ".$e->getMessage();$clase="danger";}
}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrar alumno</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/estilos.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="../index.php" class="btn btn-secondary mb-3">Volver al menú</a><div class="card shadow-sm"><div class="card-body"><h2>Registrar alumno</h2><?php if($mensaje):?><div class="alert alert-<?php echo $clase;?>"><?php echo htmlspecialchars($mensaje);?></div><?php endif;?>
<form method="post" class="row g-3"><?php foreach(["matricula"=>"Matrícula","nombre"=>"Nombre","apaterno"=>"Apellido paterno","amaterno"=>"Apellido materno","domicilio"=>"Domicilio","correo"=>"Correo electrónico","telefono"=>"Teléfono"] as $n=>$l):?><div class="col-md-6"><label class="form-label"><?php echo $l;?></label><input <?php if($n==='correo')echo 'type="email"';?> name="<?php echo $n;?>" class="form-control" required></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Estatus</label><select name="estatus" class="form-select"><option>ALTA</option><option>BAJA</option></select></div><div><button class="btn btn-primary">Guardar alumno</button></div></form></div></div></main></body></html>
